{
  "verdict": "request_changes",
  "summary": "Cache key must include tenant to satisfy per-(tenant,record_id) isolation requirement.",
  "findings": [
    {
      "finding_id": "F001",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 4,
      "severity": "critical",
      "description": "The implementation caches results only by record_id, ignoring the tenant identifier. This causes cache collisions when different tenants reference the same record_id, violating the contract that cache results should be separate for each (tenant, record_id) pair.",
      "evidence": "def lookup(cache, tenant, record_id, load):\n    if record_id not in cache:\n        cache[record_id] = load(tenant, record_id)\n    return cache[record_id]"
    }
  ]
}
